	LeaveCommunity(context.Context, *CommunityRef) (*Empty, error)
	SetCommunityMuted(context.Context, *SetCommunityMutedRequest) (*Community, error)
	ListJoinRequests(context.Context, *CommunityRef) (*ListJoinRequestsResponse, error)
	ReviewJoinRequest(context.Context, *ReviewJoinRequestRequest) (*JoinRequest, error)
